#!/usr/bin/env python
"""Reproducible search for the dev-05 GRI static formulation (shared responsive parameters).

Multiplicative coordinate descent from several starts, scored on the known cohort with the
training seed plus extra held-out meal seeds (feasibility-aware: TBR70/TBR54/min-glucose
penalties), then final validation on fresh seeds. Run: python /work/output/search.py
"""
import json, time
import numpy as np
from gri_bench.api import load_instance, Experiment, save_design, PARAMETERS

INST = load_instance()
B = {k: tuple(v) for k, v in INST['bounds'].items()}

def clip(p):
    return {k: float(min(max(p[k], B[k][0]), B[k][1])) for k in PARAMETERS}

def design(p):
    return {'mode': 'responsive', 'parameters': clip(p)}

def score(r, tbr70_lim=2.0, tbr54_lim=0.5, min_floor=55.0):
    pen = (100.0 * max(0.0, r['max_trajectory_tbr70'] - tbr70_lim)
           + 100.0 * max(0.0, r['max_trajectory_tbr54'] - tbr54_lim)
           + 5.0 * max(0.0, min_floor - r['minimum_glucose'])
           + 0.25 * max(0.0, r['mean_tir'] and 0.0))
    return r['mean_tir'] - pen, r

def coordinate_descent(exp, p0, deadline, factors=(1.7, 1.3, 1.12)):
    p = clip(p0); s, m = score(exp.evaluate(design(p)))
    n_eval = 1
    while time.time() < deadline:
        improved = False
        for k in PARAMETERS:
            for f in factors:
                for sgn in (1, -1):
                    if time.time() > deadline:
                        break
                    q = dict(p); q[k] = p[k] * (f ** sgn)
                    q = clip(q)
                    if q == p:
                        continue
                    s2, m2 = score(exp.evaluate(design(q))); n_eval += 1
                    if s2 > s:
                        p, s, m = q, s2, m2; improved = True
                    if s2 > s:
                        break
        if not improved:
            break
    return p, s, m, n_eval

if __name__ == '__main__':
    t0 = time.time()
    train_seeds = [INST['training_seeds'][0], 4001]
    exp = Experiment(INST, seeds=train_seeds)
    starts = [
        {'theta_a': 0.00025, 'relative_leak': 1.5, 'ec50_mg_dl': 130.0, 'hill_n': 3.0, 'tau_min': 10.0, 'theta_L': 2.5},
        {'theta_a': 0.00045, 'relative_leak': 1.5, 'ec50_mg_dl': 110.0, 'hill_n': 4.0, 'tau_min': 8.0, 'theta_L': 3.0},
        {'theta_a': 0.00035, 'relative_leak': 2.5, 'ec50_mg_dl': 160.0, 'hill_n': 2.0, 'tau_min': 15.0, 'theta_L': 3.5},
    ]
    deadline = t0 + 14.0
    best = None
    for p0 in starts:
        if time.time() > deadline:
            break
        p, s, m, ne = coordinate_descent(exp, p0, deadline)
        print(f'start done score={s:.2f} tir={m["mean_tir"]:.2f} tbr70={m["max_trajectory_tbr70"]:.2f} '
              f'min={m["minimum_glucose"]:.1f} params={p} evals={ne}', flush=True)
        if best is None or s > best[1]:
            best = (p, s)
    p = best[0]
    # Final validation on fresh meal seeds
    expv = Experiment(INST, seeds=[101, 202, 303])
    mv = expv.evaluate(design(p))
    mtr = exp.evaluate(design(p))
    print('FINAL train:', {k: round(v, 3) for k, v in mtr.items() if k != 'rows'})
    print('VALIDATE  :', {k: round(v, 3) for k, v in mv.items() if k != 'rows'})
    for r in mv['rows']:
        print(' ', r['patient'], r['variant'], {k: round(v, 2) for k, v in r['metrics'].items()})
    if mv['feasible'] and mtr['feasible']:
        save_design(design(p))
        json.dump({'params': p, 'train': {k: v for k, v in mtr.items() if k != 'rows'},
                   'valid': {k: v for k, v in mv.items() if k != 'rows'}},
                  open('/work/output/search_result.json', 'w'), indent=1)
    print(f'total time {time.time()-t0:.1f}s')
